import { Pressable, Text, ActivityIndicator } from 'react-native';

type TombolUtamaProps = {
  label: string;
  onTekan: () => void;
  varian?: 'utama' | 'bahaya' | 'garis';  // opsional, nilainya terbatas
  sedangMuat?: boolean;
};

export function TombolUtama({
  label,
  onTekan,
  varian = 'utama',
  sedangMuat = false,
}: TombolUtamaProps) {
  const warna = { utama: '#2563eb', bahaya: '#dc2626', garis: 'transparent' };

  return (
    <Pressable
      onPress={onTekan}
      disabled={sedangMuat}
      style={{ backgroundColor: warna[varian], padding: 14, borderRadius: 10 }}
    >
      {sedangMuat ? <ActivityIndicator color="#fff" /> : <Text>{label}</Text>}
    </Pressable>
  );
}

