import type { ReactNode } from 'react';
import { View, Text } from 'react-native';

type KartuProps = {
  judul: string;
  children: ReactNode;
  aksiKanan?: ReactNode;  // ikon atau tombol kecil di pojok — opsional
};

export function Kartu({ judul, children, aksiKanan }: KartuProps) {
  return (
    <View style={{ backgroundColor: '#fff', borderRadius: 12, padding: 16, gap: 8 }}>
      <View style={{ flexDirection: 'row', justifyContent: 'space-between' }}>
        <Text style={{ fontWeight: '600' }}>{judul}</Text>
        {aksiKanan}
      </View>
      {children}
    </View>
  );
}

