import { StyleSheet, View, Text } from 'react-native';

const styles = StyleSheet.create({
  kartu: {
    backgroundColor: '#fff',
    borderRadius: 12,
    padding: 16,
  },
  harga: {
    fontSize: 18,
    fontWeight: '600',   // string literal, bukan angka 600
    color: '#16a34a',
  },
});

// styles.kartu bertipe ViewStyle, styles.harga bertipe TextStyle —
// tanpa satu pun anotasi yang kamu tulis.
<View style={styles.kartu}>
  <Text style={styles.harga}>Rp 250.000</Text>
</View>

import type { StyleProp, ViewStyle } from 'react-native';
import { View, Text, StyleSheet } from 'react-native';

type KartuProdukProps = {
  nama: string;
  harga: number;
  style?: StyleProp<ViewStyle>;   // pemakai boleh menimpa sebagian
};

export function KartuProduk({ nama, harga, style }: KartuProdukProps) {
  return (
    <View style={[styles.dasar, style]}>
      {/* array: style bawaan dulu, style dari luar menimpa di atasnya */}
      <Text>{nama}</Text>
      <Text>Rp {harga.toLocaleString('id-ID')}</Text>
    </View>
  );
}

